INSERT INTO `news` (`id`, `title`, `content`, `image`, `is_active`, `created_at`) VALUES
(6, 'الاخبار', 'ترحب وكالة الغزالي للسفريات والسياحة بعملائها الكرام\r\nونود أن نعلمكم باستمرار تقديم خدماتنا في مجال حجوزات الطيران، التأشيرات، خدمات العمرة، حجز الفنادق، النقل السياحي، ومتابعة المعاملات بكل احترافية وسرعة.\r\nكما نعمل بشكل دائم على تطوير خدماتنا لتلبية احتياجات عملائنا وتوفير أفضل الحلول في مجال السفر والسياحة، مع الحرص على الدقة، المصداقية، وسرعة الإنجاز.\r\nتابعوا آخر عروضنا وخدماتنا الجديدة باستمرار\r\nونسعد دائماً بخدمتكم والرد على جميع استفساراتكم.\r\nوكالة الغزالي للسفريات والسياحة\r\nثقتكم هي أساس نجاحنا، وخدمتكم شرف لنا.', NULL, 1, '2026-03-13 07:39:22');
