INSERT INTO `services` (`id`, `service_name`, `service_image`, `price`, `nights_count`, `hotel_name`, `makkah_days`, `madinah_days`, `quad_price`, `triple_price`, `double_price`, `created_at`, `currency_id`, `print_terms`, `service_type`, `status`, `revenue_account_id`, `cost_account_id`, `profit_account_id`) VALUES
(1, 'النقل البري', 'https://alghazali1.odoo.com/web/image/429-e7f9ee80/1000516536.svg', 0.00, 0, 'حسب الطلب', 0, 0, 0.00, 0.00, 0.00, '2026-02-16 23:16:45', 3, NULL, 'other', 'active', 34, 46, 133),
(2, 'جوازت السفر', 'https://alghazali1.odoo.com/web/image/432-f49c3af0/1000516615.svg', 0.00, 0, 'حسب الطلب', 0, 0, 0.00, 0.00, 0.00, '2026-02-16 23:16:45', 3, '', NULL, 'active', 39, 51, 138),
(3, 'تذاكر طيران', 'https://alghazali1.odoo.com/web/image/433-5a7aab84/1000516535.svg', 0.00, 0, 'حسب الطلب', 0, 0, 0.00, 0.00, 0.00, '2026-02-16 23:16:45', 3, NULL, 'other', 'active', 35, 47, 134),
(4, 'خدمات العمرة', 'https://alghazali1.odoo.com/web/image/431-7aeea8cc/1000516571.svg', 0.00, 0, 'حسب الطلب', 0, 0, 0.00, 0.00, 0.00, '2026-02-16 23:16:45', 3, NULL, 'umrah', 'active', 37, 49, 136),
(5, 'الزيارة العائلية', 'https://alghazali1.odoo.com/web/image/434-5652a127/1000516539.svg', 0.00, 0, 'حسب الطلب', 0, 0, 0.00, 0.00, 0.00, '2026-02-16 23:16:45', 3, 'شروط وأحكام خدمات الزيارة العائلية:\r\n\r\n1. أهلية الزيارة:\r\n   - يجب أن تكون صلة القرابة مع المستضيف معترف بها قانونيًا (زوج، زوجة، أبناء، آباء، إخوة، أخوات، إلخ).\r\n   - المستضيف يجب أن يكون مقيمًا قانونيًا في البلد المضيف.\r\n   - يجب تقديم إثباتات صلة القرابة (شهادات ولادة، شهادات زواج، إلخ).\r\n\r\n2. الوثائق المطلوبة:\r\n   - جواز سفر ساري لمدة لا تقل عن 6 أشهر من تاريخ السفر.\r\n   - صور شخصية بحجم جواز السفر.\r\n   - خطاب دعوة من المستضيف موثق من السلطات المحلية.\r\n   - إثبات إقامة المستضيف في البلد المضيف.\r\n   - إثبات علاقة القرابة.\r\n\r\n3. التسعير والدفع:\r\n   - الأسعار تختلف حسب مدة الزيارة والعلاقة.\r\n   - يجب دفع المبلغ بالكامل قبل بدء معالجة الطلب.\r\n   - في حال رفض الطلب من الجهات المختصة، يتم استرداد 70% من المبلغ بعد خصم رسوم إدارية.\r\n   - لا يتم استرداد أي مبلغ في حال تمت الموافقة ثم ألغى العميل الطلب.\r\n\r\n4. المدة والمعالجة:\r\n   - مدة معالجة الطلب: من 7 إلى 21 يوم عمل.\r\n   - مدة الزيارة: حسب نوع التأشيرة الممنوحة (عادة 30، 60، أو 90 يومًا).\r\n   - الشركة غير مسؤولة عن أي تأخير من قبل السفارات أو الجهات الحكومية.\r\n\r\n5. المسؤولية:\r\n   - يتحمل العميل مسؤولية صحة جميع الوثائق المقدمة.\r\n   - الشركة غير مسؤولة عن رفض الطلب من قبل الجهات المختصة.\r\n   - العميل مسؤول عن الالتزام بقوانين البلد المضيف خلال فترة الزيارة.\r\n   - الزيارة لا تعتبر عرضًا للعمل أو الإقامة الدائمة.\r\n\r\n6. الشروط العامة:\r\n   - تحتفظ الشركة بالحق في تعديل هذه الشروط دون إشعار مسبق.\r\n   - أي نزاع يخضع لقوانين البلد المضيف.\r\n   - بإرسال الطلب، يعتبر العميل قد قر ووافق على جميع هذه الشروط والأحكام.\r\n\r\nشكرًا لثقتكم بنا! نتمنى لكم زيارة سعيدة وآمنة.', 'family_visit', 'active', 38, 50, 137),
(6, 'فيز العمل', 'https://alghazali1.odoo.com/web/image/430-5f9bd5a2/1000516600.svg', 0.00, 0, 'حسب الطلب', 0, 0, 0.00, 0.00, 0.00, '2026-02-16 23:16:45', 3, NULL, 'work_visa', 'active', 36, 48, 135),
(7, 'خدمات الحج', 'https://alghazali1.odoo.com/web/image/431-7aeea8cc/1000516571.svg', 0.00, 0, 'حسب الطلب', 0, 0, 0.00, 0.00, 0.00, '2026-06-07 18:59:44', 3, NULL, 'umrah', 'active', 147, 149, 150),
(8, 'خدمات البريد', NULL, 0.00, NULL, NULL, NULL, NULL, NULL, NULL, NULL, '2026-06-17 11:35:17', NULL, NULL, 'postal', 'active', 151, 152, 153);
