INSERT INTO `site_content` (`id`, `section_key`, `section_title`, `section_text`, `section_image`, `updated_at`, `meta_title`, `meta_description`, `meta_keywords`) VALUES
(1, 'about_summary', 'من نحن', 'نحن وكالة الغزالي للسفريات والسياحة، ملتزمون بتحقيق أحلام عطلتك!', NULL, '2026-02-16 22:27:22', NULL, NULL, NULL),
(2, 'hajj_umrah', 'الحج والعمرة', 'تعمل شركة الغزالي الدولية لخدمات المعتمرين والزوار في هذا المجال منذ أكثر من خمس سنوات...', NULL, '2026-02-16 22:27:22', NULL, NULL, NULL),
(3, 'mission', 'الرسالة', 'نسعى للرقي بخدمات الحج والعمرة وبرامج السياحة والسفر بجودة وتميز لنيل رضى عملاءنا...', NULL, '2026-02-16 22:27:22', NULL, NULL, NULL),
(4, 'vision', 'الرؤية', 'خدمات مميزة بجودة واتقان، اداء المناسك بسهولة ويسر، السعى المستمر لتحقيق رغبات العميل...', NULL, '2026-02-16 22:27:22', NULL, NULL, NULL),
(5, 'goal', 'الهدف', 'تجربة سفر سهلة و ممتعة ومليئة بالسعادة وخدمات مميزة ومتطوره...', NULL, '2026-02-16 22:27:22', NULL, NULL, NULL);
