CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_ensure_opening_balance` (IN `p_account_id` INT, IN `p_currency_id` INT, IN `p_opening_balance` DECIMAL(18,2), IN `p_credit_limit` DECIMAL(18,2), IN `p_created_by` INT, IN `p_ip_address` VARCHAR(45), IN `p_user_agent` TEXT)  MODIFIES SQL DATA SQL SECURITY INVOKER COMMENT '[PATCH:NO_TX] إنشاء افتتاحية حساب/عملة إذا لم تكن موجودة — NO TX' BEGIN
    DECLARE v_currency_code VARCHAR(10);
    DECLARE v_new_json JSON;
    SET p_ip_address = fn_sanitize_safe(p_ip_address, 1);
    SET p_user_agent = fn_sanitize_safe(p_user_agent, 0);
    IF p_account_id IS NULL OR p_currency_id IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'sp_ensure_opening_balance: معرف الحساب أو العملة فارغ';
    END IF;
    SELECT currency_code INTO v_currency_code FROM currencies WHERE id = p_currency_id LIMIT 1;
        account_id, branch_id, currency_id, currency_code,
        opening_balance, current_balance, current_balance_base,
        credit_limit, debit_limit, is_frozen,
        last_updated, opening_balance_base, created_by
    ) VALUES (
        p_account_id, NULL, p_currency_id, v_currency_code,
        COALESCE(p_opening_balance, 0),
        COALESCE(p_opening_balance, 0),
        COALESCE(p_opening_balance, 0) * COALESCE((SELECT exchange_rate FROM currencies WHERE id = p_currency_id), 1.0),
        COALESCE(p_credit_limit, 0),
        0, 0,
        NOW(),
        0,
        p_created_by
    );
    IF COALESCE(p_opening_balance, 0) <> 0 OR COALESCE(p_credit_limit, 0) <> 0 THEN
        UPDATE account_balances_unified
           SET opening_balance = COALESCE(p_opening_balance, opening_balance),
               credit_limit    = COALESCE(NULLIF(p_credit_limit, 0), credit_limit),
               last_updated    = NOW()
         WHERE account_id = p_account_id AND currency_id = p_currency_id;
    END IF;
    CALL sp_rebuild_balances();
    SET v_new_json = JSON_OBJECT(
        'account_id',      p_account_id,
        'currency_id',     p_currency_id,
        'currency_code',   v_currency_code,
        'opening_balance', CAST(COALESCE(p_opening_balance, 0) AS CHAR),
        'credit_limit',    CAST(COALESCE(p_credit_limit, 0) AS CHAR)
    );
        user_id, action, table_name, record_id,
        old_values, new_values, ip_address, user_agent, created_at
    ) VALUES (
        COALESCE(p_created_by, 0),
        'ensure_opening',
        'account_balances_unified',
        p_account_id,
        NULL,
        CAST(v_new_json AS CHAR),
        NULLIF(p_ip_address, ''),
        p_user_agent,
        NOW()
    );
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_log_error` (IN `p_procedure_name` VARCHAR(100), IN `p_error_message` TEXT, IN `p_user_id` INT, IN `p_context_json` JSON)  MODIFIES SQL DATA SQL SECURITY INVOKER COMMENT '[محاسبي] تسجيل أخطاء الإجراءات المخزنة في audit_logs' sp_log_error_body:BEGIN
    DECLARE v_ip VARCHAR(45) DEFAULT NULL;
    DECLARE v_ua TEXT        DEFAULT NULL;

    IF p_user_id IS NOT NULL THEN
        BEGIN
            DECLARE CONTINUE HANDLER FOR SQLEXCEPTION BEGIN END;
            SET v_ip = (
                SELECT SUBSTRING_INDEX(
                    GROUP_CONCAT(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(new_values, '$.ip_address')), '')
                                 ORDER BY id DESC SEPARATOR '|'), '|', 1)
                  FROM audit_logs WHERE user_id = p_user_id LIMIT 1
            );
        END;
    END IF;

        user_id, action, table_name, record_id,
        old_values, new_values, ip_address, user_agent, created_at
    ) VALUES (
        COALESCE(p_user_id, 0), 'error', COALESCE(p_procedure_name, 'unknown'), 0,
        COALESCE(CAST(p_context_json AS CHAR), '{}'),
        JSON_OBJECT(
            'error_message', LEFT(COALESCE(p_error_message, ''), 2000),
            'procedure_name', COALESCE(p_procedure_name, 'unknown'),
            'logged_at', DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')
        ),
        v_ip, v_ua, NOW()
    );
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_post_expense_voucher` (IN `p_voucher_id` INT, IN `p_posted_by` INT)  MODIFIES SQL DATA SQL SECURITY INVOKER COMMENT '[المصروفات] ترحيل المصروف — قيد يومية مدين المصروف + دائن الصندوق + تحديث أرصدة' sp_post_ev_body:BEGIN
    DECLARE v_status              VARCHAR(50);
    DECLARE v_exp_acc_id          INT;
    DECLARE v_cash_acc_id         INT;
    DECLARE v_currency_id         INT;
    DECLARE v_exchange_rate       DECIMAL(18,6);
    DECLARE v_total_amount        DECIMAL(18,4);
    DECLARE v_tax_amount          DECIMAL(18,4);
    DECLARE v_description         TEXT;
    DECLARE v_budget_id           INT;
    DECLARE v_created_by          INT;
    DECLARE v_before_json         JSON;
    DECLARE v_after_json          JSON;
    DECLARE v_posted_ip           VARCHAR(45) DEFAULT NULL;
    DECLARE v_posted_ua           TEXT        DEFAULT NULL;
    DECLARE v_branch_id           INT;
    DECLARE v_cost_center_id      INT;
    DECLARE v_supplier_id         INT;
    DECLARE v_voucher_number      VARCHAR(50);
    DECLARE v_tx_id               INT;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        DECLARE v_ctx JSON;
        ROLLBACK;
        GET DIAGNOSTICS CONDITION 1
            @err_sqlstate = RETURNED_SQLSTATE,
            @err_msg      = MESSAGE_TEXT,
            @err_no       = MYSQL_ERRNO;
        SET v_ctx = JSON_OBJECT(
            'voucher_id',   CAST(p_voucher_id AS CHAR),
            'posted_by',    CAST(p_posted_by AS CHAR),
            'mysql_errno',  CAST(@err_no AS CHAR),
            'sqlstate',     @err_sqlstate
        );
        CALL sp_log_error('sp_post_expense_voucher', @err_msg, p_posted_by, v_ctx);
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'تعذر إتمام العملية. يرجى مراجعة البيانات والمحاولة مرة أخرى.';
    END;

    START TRANSACTION;

    IF p_voucher_id IS NULL OR p_voucher_id <= 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'تعذر ترحيل المصروف: معرف السند غير صالح.';
    END IF;

    SELECT ev.status, ev.expense_account_id, ev.cash_bank_account_id,
           ev.currency_id, ev.exchange_rate, ev.total_amount, ev.tax_amount,
           ev.description, ev.budget_id, COALESCE(ev.created_by, 0),
           ev.branch_id, ev.cost_center_id, ev.supplier_id, ev.voucher_number
      INTO v_status, v_exp_acc_id, v_cash_acc_id,
           v_currency_id, v_exchange_rate, v_total_amount, v_tax_amount,
           v_description, v_budget_id, v_created_by,
           v_branch_id, v_cost_center_id, v_supplier_id, v_voucher_number
      FROM expense_vouchers ev
     WHERE ev.id = p_voucher_id
     LIMIT 1;

    IF v_status IS NULL THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'تعذر ترحيل المصروف: السند غير موجود.';
    END IF;

    IF v_status = 'posted' THEN
        LEAVE sp_post_ev_body;
    END IF;

    IF v_status NOT IN ('draft','approved') THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'تعذر ترحيل المصروف: الحالة الحالية لا تسمح بالترحيل.';
    END IF;

    IF p_posted_by IS NOT NULL THEN
        BEGIN
            DECLARE CONTINUE HANDLER FOR SQLEXCEPTION BEGIN END;
            SET v_posted_ip = (
                SELECT SUBSTRING_INDEX(
                    GROUP_CONCAT(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(new_values, '$.ip_address')), '')
                                 ORDER BY id DESC SEPARATOR '|'), '|', 1)
                  FROM audit_logs WHERE user_id = p_posted_by LIMIT 1
            );
        END;
    END IF;

    -- (1) إنشاء معاملة مالية من نوع "expense"
        transaction_number, transaction_date, transaction_type,
        reference_type, reference_id, branch_id,
        party_account_id, cash_bank_account_id,
        currency_id, amount, exchange_rate,
        status, description,
        created_by, posted_by, created_at, posted_at,
        created_ip, posted_ip
    ) VALUES (
        v_voucher_number, CURDATE(), 'expense',
        'expense_voucher', p_voucher_id, v_branch_id,
        v_supplier_id, v_cash_acc_id,
        v_currency_id, v_total_amount, COALESCE(NULLIF(v_exchange_rate, 0), 1.0),
        'posted', v_description,
        COALESCE(v_created_by, p_posted_by, 0), p_posted_by, NOW(), NOW(),
        v_posted_ip, v_posted_ip
    );
    SET v_tx_id = LAST_INSERT_ID();

    -- (2) قيد اليومية:
    --     مدين = حساب المصروف (expense)
    --     دائن = حساب الصندوق/البنك (asset)
        financial_transaction_id, line_number,
        account_id, account_type, currency_id,
        debit, credit, base_debit, base_credit,
        description, line_type, created_at
    ) VALUES (
        v_tx_id, 1,
        v_exp_acc_id, 'expense', v_currency_id,
        v_total_amount, 0,
        v_total_amount * COALESCE(NULLIF(v_exchange_rate, 0), 1.0), 0,
        v_description, 'expense_debit', NOW()
    );

    IF COALESCE(v_tax_amount, 0) > 0 THEN
        -- قيد ضريبة القيمة المضافة على المصروف (ذمم مدينة ضريبة مدين)
            financial_transaction_id, line_number,
            account_id, account_type, currency_id,
            debit, credit, base_debit, base_credit,
            description, line_type, created_at
        ) VALUES (
            v_tx_id, 2,
            (SELECT id FROM unified_accounts WHERE account_type = 'vat_receivable' LIMIT 1),
            'asset', v_currency_id,
            v_tax_amount, 0,
            v_tax_amount * COALESCE(NULLIF(v_exchange_rate, 0), 1.0), 0,
            'ضريبة مدخلة على المصروف', 'vat_debit', NOW()
        );
    END IF;

        financial_transaction_id, line_number,
        account_id, account_type, currency_id,
        debit, credit, base_debit, base_credit,
        description, line_type, created_at
    ) VALUES (
        v_tx_id, IF(COALESCE(v_tax_amount,0)>0, 3, 2),
        v_cash_acc_id, 'asset', v_currency_id,
        0, v_total_amount + COALESCE(v_tax_amount, 0),
        0, (v_total_amount + COALESCE(v_tax_amount, 0)) * COALESCE(NULLIF(v_exchange_rate, 0), 1.0),
        v_description, 'cash_credit', NOW()
    );

    CALL sp_validate_journal_balance(v_tx_id);

    -- (3) تحديث حالة سند المصروف إلى مرحل
    UPDATE expense_vouchers
       SET status       = 'posted',
           posted_by    = p_posted_by,
           posted_at    = NOW(),
           posted_ip    = v_posted_ip
     WHERE id = p_voucher_id;

    -- (4) استهلاك رصيد الميزانية نهائياً (تحويل من committed إلى consumed)
    IF v_budget_id IS NOT NULL THEN
        CALL sp_consume_budget(v_budget_id, v_exp_acc_id, v_total_amount, 'consume');
    END IF;

    -- (5) سجل المراجعة
    SET v_before_json = JSON_OBJECT('id', CAST(p_voucher_id AS CHAR), 'old_status', v_status);
    SET v_after_json  = JSON_OBJECT(
        'id',                  CAST(p_voucher_id AS CHAR),
        'new_status',          'posted',
        'transaction_id',      CAST(v_tx_id AS CHAR),
        'posted_by',           CAST(p_posted_by AS CHAR),
        'journal_lines_count', CAST(IF(COALESCE(v_tax_amount,0)>0,3,2) AS CHAR)
    );
        user_id, action, table_name, record_id,
        old_values, new_values, ip_address, user_agent, created_at
    ) VALUES (
        COALESCE(p_posted_by, v_created_by, 0),
        'post', 'expense_vouchers', p_voucher_id,
        CAST(v_before_json AS CHAR), CAST(v_after_json AS CHAR),
        v_posted_ip, v_posted_ua, NOW()
    );

    -- (6) تحديث الأرصدة
    CALL sp_update_account_balances();

    COMMIT;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_post_invoice` (IN `p_invoice_id` INT, IN `p_posted_by` INT)  MODIFIES SQL DATA SQL SECURITY INVOKER COMMENT '[PATCH:TX_ADDED][PHP-compat:2IN] ?????????? ???????????? ??? TX ADDED ??? ?????????? + ?????????? + ???????? + IP' sp_post_invoice_body:BEGIN
    DECLARE v_category          ENUM('sales','purchase');
    DECLARE v_status            VARCHAR(20);
    DECLARE v_total_amount      DECIMAL(15,2);
    DECLARE v_net_amount        DECIMAL(15,2);
    DECLARE v_currency_id       INT;
    DECLARE v_discount          DECIMAL(15,2);
    DECLARE v_description       TEXT;
    DECLARE v_created_by        INT;
    DECLARE v_customer_id       INT;
    DECLARE v_supplier_id       INT;
    DECLARE v_branch_id         INT;
    DECLARE v_party_id          INT;
    DECLARE v_party_account_id  INT;
    DECLARE v_account_type      VARCHAR(50);
    DECLARE v_tax_amount        DECIMAL(15,2) DEFAULT 0;
    DECLARE v_party_currency    INT         DEFAULT NULL;
    DECLARE v_credit_limit      DECIMAL(18,2) DEFAULT NULL;
    DECLARE v_curr_balance      DECIMAL(18,2) DEFAULT 0;
    DECLARE v_revenue_acct      INT;
    DECLARE v_cogs_acct         INT;
    DECLARE v_ar_acct           INT;
    DECLARE v_ap_acct           INT;
    DECLARE v_tx_id             INT;
    DECLARE v_trx_num           VARCHAR(50);
    DECLARE v_posted_ip         VARCHAR(45) DEFAULT NULL;
    DECLARE v_created_ua        TEXT        DEFAULT NULL;
    DECLARE v_before_json       JSON;
    DECLARE v_after_json        JSON;
    DECLARE v_old_inv_json      JSON;
    DECLARE v_exchange_rate     DECIMAL(18,6);
    DECLARE v_cost_amount       DECIMAL(15,2);

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;

    START TRANSACTION;

    IF p_invoice_id IS NULL OR p_invoice_id <= 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'sp_post_invoice: ???????? ???????????????? ?????? ????????';
    END IF;
    SELECT invoice_category, invoice_status, total_amount,
           net_amount, currency_id, discount, description,
           COALESCE(created_by,0), customer_id, supplier_id, branch_id, exchange_rate, cost_amount
      INTO v_category, v_status, v_total_amount,
           v_net_amount, v_currency_id, v_discount, v_description,
           v_created_by, v_customer_id, v_supplier_id, v_branch_id, v_exchange_rate, v_cost_amount
      FROM invoices
     WHERE id = p_invoice_id
     LIMIT 1;
    IF v_status IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'sp_post_invoice: ???????????????? ?????? ????????????';
    END IF;
    IF v_status = 'posted' THEN
        LEAVE sp_post_invoice_body;
    END IF;
    IF v_status NOT IN ('draft','review','approved','partial') THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'sp_post_invoice: ???????? ???????????????? ?????? ?????????? ??????????????';
    END IF;
    SET v_tax_amount = 0;
    SET v_revenue_acct = fn_get_default_leaf_account('revenue');
    SET v_cogs_acct    = fn_get_default_leaf_account('expense');
    SET v_ar_acct      = fn_get_default_leaf_account('accounts_receivable');
    SET v_ap_acct      = fn_get_default_leaf_account('accounts_payable');
    IF v_category = 'sales' THEN
        SET v_party_id         = v_customer_id;
        SET v_account_type     = 'customer';
        SET v_party_account_id = (SELECT account_id FROM customers WHERE id = v_customer_id);
    ELSE
        SET v_party_id         = v_supplier_id;
        SET v_account_type     = 'supplier';
        SET v_party_account_id = (SELECT account_id FROM suppliers WHERE id = v_supplier_id);
    END IF;
    IF v_party_account_id IS NOT NULL AND v_currency_id IS NOT NULL THEN
        BEGIN
            DECLARE v_match INT DEFAULT 0;
            SELECT DISTINCT currency_id INTO v_party_currency
              FROM account_balances_unified
             WHERE account_id = v_party_account_id
             ORDER BY CASE WHEN currency_id = v_currency_id THEN 0 ELSE 1 END
             LIMIT 1;
            SELECT COUNT(*) INTO v_match
              FROM account_balances_unified
             WHERE account_id = v_party_account_id AND currency_id = v_currency_id;
            IF v_match = 0 AND v_party_currency IS NOT NULL THEN
                SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT =
                    'sp_post_invoice: ???????? ???????????????? ???? ?????????? ???????? ???????? ????????????/????????????';
            END IF;
        END;
    END IF;
    IF v_category = 'sales' AND v_party_account_id IS NOT NULL AND v_currency_id IS NOT NULL THEN
        BEGIN
            SELECT credit_limit, current_balance
              INTO v_credit_limit, v_curr_balance
              FROM account_balances_unified
             WHERE account_id = v_party_account_id AND currency_id = v_currency_id
             LIMIT 1;
            SET v_credit_limit = COALESCE(v_credit_limit,
                (SELECT COALESCE(default_credit_limit, 0) FROM customers WHERE id = v_party_id));
            SET v_credit_limit = COALESCE(v_credit_limit, 0);
            IF v_credit_limit > 0 THEN
                IF (v_curr_balance + v_net_amount) > v_credit_limit THEN
                    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT =
                        'sp_post_invoice: ?????????? ???? ???????????????? ?????????????? ????????????';
                END IF;
            END IF;
        END;
    END IF;
    IF p_posted_by IS NOT NULL THEN
        BEGIN
            DECLARE CONTINUE HANDLER FOR SQLEXCEPTION BEGIN END;
            SET v_posted_ip = (SELECT SUBSTRING_INDEX(
                GROUP_CONCAT(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(new_values, '$.ip_address')), '') ORDER BY id DESC SEPARATOR '|'), '|', 1)
              FROM audit_logs WHERE user_id = p_posted_by LIMIT 1);
        END;
    END IF;
    SET v_old_inv_json = JSON_OBJECT(
        'id',               p_invoice_id,
        'invoice_category', v_category,
        'invoice_status',   v_status,
        'net_amount',       CAST(v_net_amount AS CHAR),
        'currency_id',      CAST(v_currency_id AS CHAR)
    );
    SET v_trx_num = fn_get_next_sequence('journal');
        transaction_number, transaction_date, transaction_type,
        reference_type, reference_id, branch_id,
        party_account_id, currency_id, amount, exchange_rate,
        description, status, posted_by, posted_at,
        created_by, created_at, created_ip, created_user_agent,
        posted_ip
    ) VALUES (
        v_trx_num, CURDATE(), CASE WHEN v_category='sales' THEN 'invoice' ELSE 'purchase' END,
        'invoice', p_invoice_id, v_branch_id,
        v_party_account_id, v_currency_id, v_total_amount,
        COALESCE(NULLIF(v_exchange_rate, 0), 1.0),
        v_description, 'posted',
        p_posted_by, NOW(),
        v_created_by, NOW(), v_posted_ip, v_created_ua,
        v_posted_ip
    );
    SET v_tx_id = LAST_INSERT_ID();
    IF v_category = 'sales' THEN
            financial_transaction_id, line_number,
            account_id, account_type, currency_id,
            debit, credit, base_debit, base_credit,
            description, line_type, created_at
        ) VALUES (
            v_tx_id, 1,
            COALESCE(v_party_account_id, v_ar_acct), 'customer', v_currency_id,
            v_net_amount, 0, v_net_amount * COALESCE(NULLIF(v_exchange_rate, 0), 1.0), 0,
            v_description, 'main', NOW()
        );
        IF v_discount > 0 THEN
                financial_transaction_id, line_number,
                account_id, account_type, currency_id,
                debit, credit, base_debit, base_credit,
                description, line_type, created_at
            ) VALUES (
                v_tx_id, 2,
                v_revenue_acct, 'revenue', v_currency_id,
                0, v_discount, 0, v_discount * COALESCE(NULLIF(v_exchange_rate, 0), 1.0),
                '?????? ?????? ????????????????', 'discount', NOW()
            );
        END IF;
            financial_transaction_id, line_number,
            account_id, account_type, currency_id,
            debit, credit, base_debit, base_credit,
            description, line_type, created_at
        ) VALUES (
            v_tx_id, 3,
            v_revenue_acct, 'revenue', v_currency_id,
            0, v_net_amount + v_discount, 0, (v_net_amount + v_discount) * COALESCE(NULLIF(v_exchange_rate, 0), 1.0),
            v_description, 'revenue', NOW()
        );
        IF COALESCE(v_cost_amount, 0) > 0 THEN
                financial_transaction_id, line_number,
                account_id, account_type, currency_id,
                debit, credit, base_debit, base_credit,
                description, line_type, created_at
            ) VALUES (
                v_tx_id, 4,
                v_cogs_acct, 'expense', v_currency_id,
                v_cost_amount, 0,
                v_cost_amount * COALESCE(NULLIF(v_exchange_rate, 0), 1.0), 0,
                '?????????? ?????????????? ??????????????', 'cogs', NOW()
            );
                financial_transaction_id, line_number,
                account_id, account_type, currency_id,
                debit, credit, base_debit, base_credit,
                description, line_type, created_at
            ) VALUES (
                v_tx_id, 5,
                v_revenue_acct, 'asset', v_currency_id,
                0, v_cost_amount,
                0, v_cost_amount * COALESCE(NULLIF(v_exchange_rate, 0), 1.0),
                '?????????? ??????????????', 'cogs_credit', NOW()
            );
        END IF;
    ELSE
            financial_transaction_id, line_number,
            account_id, account_type, currency_id,
            debit, credit, base_debit, base_credit,
            description, line_type, created_at
        ) VALUES (
            v_tx_id, 1,
            v_cogs_acct, 'expense', v_currency_id,
            v_net_amount, 0,
            v_net_amount * COALESCE(NULLIF(v_exchange_rate, 0), 1.0), 0,
            v_description, 'purchase_expense', NOW()
        );
            financial_transaction_id, line_number,
            account_id, account_type, currency_id,
            debit, credit, base_debit, base_credit,
            description, line_type, created_at
        ) VALUES (
            v_tx_id, 2,
            COALESCE(v_party_account_id, v_ap_acct), 'supplier', v_currency_id,
            0, v_net_amount,
            0, v_net_amount * COALESCE(NULLIF(v_exchange_rate, 0), 1.0),
            v_description, 'payable', NOW()
        );
    END IF;
    CALL sp_validate_journal_balance(v_tx_id);
    UPDATE invoices
       SET invoice_status = 'posted',
           posted_by    = p_posted_by,
           posted_at    = NOW()
     WHERE id = p_invoice_id;
    SET v_before_json = JSON_OBJECT(
        'id',               p_invoice_id,
        'invoice_category', v_category,
        'invoice_status',   v_status,
        'net_amount',       CAST(v_net_amount AS CHAR)
    );
    SET v_after_json = JSON_OBJECT(
        'id',               p_invoice_id,
        'invoice_category', v_category,
        'invoice_status',   'posted',
        'net_amount',       CAST(v_net_amount AS CHAR),
        'posted_by',        CAST(p_posted_by AS CHAR),
        'transaction_id',   CAST(v_tx_id AS CHAR)
    );
        user_id, action, table_name, record_id,
        old_values, new_values, ip_address, user_agent, created_at
    ) VALUES (
        COALESCE(p_posted_by, v_created_by, 0),
        'post', 'invoices', p_invoice_id,
        CAST(v_before_json AS CHAR), CAST(v_after_json AS CHAR),
        v_posted_ip, v_created_ua, NOW()
    );
        user_id, action, table_name, record_id,
        old_values, new_values, ip_address, user_agent, created_at
    ) VALUES (
        COALESCE(p_posted_by, v_created_by, 0),
        'post', 'financial_transactions', v_tx_id,
        NULL, CAST(v_old_inv_json AS CHAR),
        v_posted_ip, v_created_ua, NOW()
    );
    CALL sp_recalculate_invoice_payment(p_invoice_id);
    CALL sp_update_account_balances();

    COMMIT;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_post_payment_voucher` (IN `p_transaction_id` INT, IN `p_posted_by` INT)  MODIFIES SQL DATA SQL SECURITY INVOKER COMMENT '[V2] ترحيل سند صرف — TX + EXIT HANDLER + رسائل عامة + عكس القيد + AP' sp_post_pv_body:BEGIN
    DECLARE v_status          VARCHAR(20);
    DECLARE v_amount          DECIMAL(18,4);
    DECLARE v_currency_id     INT;
    DECLARE v_exchange_rate   DECIMAL(18,6);
    DECLARE v_party_account_id INT;
    DECLARE v_cash_bank_id    INT;
    DECLARE v_description     TEXT;
    DECLARE v_created_by      INT;
    DECLARE v_before_json     JSON;
    DECLARE v_after_json      JSON;
    DECLARE v_inv_id          INT;
    DECLARE v_alloc_amount    DECIMAL(18,4);
    DECLARE v_inv_net         DECIMAL(18,2);
    DECLARE v_inv_paid        DECIMAL(18,2);
    DECLARE v_alloc_rem       DECIMAL(18,2);
    DECLARE v_posted_ip       VARCHAR(45) DEFAULT NULL;
    DECLARE v_posted_ua       TEXT        DEFAULT NULL;
    DECLARE v_ap_account_id   INT;
    DECLARE v_cash_account_id INT;
    DECLARE done INT DEFAULT 0;
    DECLARE cur CURSOR FOR
        SELECT invoice_id, allocated_amount
          FROM payment_allocations
         WHERE financial_transaction_id = p_transaction_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        DECLARE v_ctx JSON;
        ROLLBACK;
        GET DIAGNOSTICS CONDITION 1
            @err_sqlstate = RETURNED_SQLSTATE,
            @err_msg      = MESSAGE_TEXT,
            @err_no       = MYSQL_ERRNO;
        SET v_ctx = JSON_OBJECT(
            'transaction_id', CAST(p_transaction_id AS CHAR),
            'posted_by',      CAST(p_posted_by AS CHAR),
            'mysql_errno',    CAST(@err_no AS CHAR),
            'sqlstate',       @err_sqlstate
        );
        CALL sp_log_error('sp_post_payment_voucher', @err_msg, p_posted_by, v_ctx);
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'تعذر إتمام العملية. يرجى مراجعة البيانات والمحاولة مرة أخرى.';
    END;

    START TRANSACTION;

    IF p_transaction_id IS NULL OR p_transaction_id <= 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'تعذر إتمام العملية: معرف السند غير صالح.';
    END IF;

    -- جلب بيانات سند الصرف + التأكد من وجوده
    SELECT status, amount, currency_id, exchange_rate,
           party_account_id, cash_bank_account_id, description,
           COALESCE(created_by, 0)
      INTO v_status, v_amount, v_currency_id, v_exchange_rate,
           v_party_account_id, v_cash_bank_id, v_description, v_created_by
      FROM financial_transactions
     WHERE id = p_transaction_id AND transaction_type = 'payment'
     LIMIT 1;

    IF v_status IS NULL THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'تعذر إتمام العملية: السند المطلوب غير متوفر.';
    END IF;

    IF v_status = 'posted' THEN
        LEAVE sp_post_pv_body;
    END IF;

    IF v_status <> 'draft' THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'تعذر إتمام العملية: حالة السند الحالية لا تسمح بالترحيل.';
    END IF;

    IF COALESCE(v_amount, 0) <= 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'تعذر إتمام العملية: مبلغ السند يجب أن يكون أكبر من صفر.';
    END IF;

    -- حسابات ذمم دائنة (حسابات دائنة - موردين) + الصندوق/البنك
    SET v_ap_account_id = COALESCE(
        v_party_account_id,
        (SELECT id FROM unified_accounts WHERE account_type = 'accounts_payable' LIMIT 1)
    );
    SET v_cash_account_id = COALESCE(
        v_cash_bank_id,
        (SELECT id FROM unified_accounts WHERE account_type IN ('box','bank') LIMIT 1)
    );

    IF v_ap_account_id IS NULL OR v_cash_account_id IS NULL THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'تعذر إتمام العملية: بعض الحسابات المحاسبية الأساسية غير مهيأة.';
    END IF;

    IF p_posted_by IS NOT NULL THEN
        BEGIN
            DECLARE CONTINUE HANDLER FOR SQLEXCEPTION BEGIN END;
            SET v_posted_ip = (
                SELECT SUBSTRING_INDEX(
                    GROUP_CONCAT(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(new_values, '$.ip_address')), '')
                                 ORDER BY id DESC SEPARATOR '|'), '|', 1)
                  FROM audit_logs WHERE user_id = p_posted_by LIMIT 1
            );
        END;
    END IF;

    SET v_before_json = JSON_OBJECT(
        'id',                   CAST(p_transaction_id AS CHAR),
        'status',               v_status,
        'amount',               CAST(v_amount AS CHAR),
        'currency_id',          CAST(v_currency_id AS CHAR),
        'party_account_id',     CAST(v_party_account_id AS CHAR),
        'cash_bank_account_id', CAST(v_cash_bank_id AS CHAR)
    );

    -- ===================================================================
    -- قيد الصرف: (عكس القبض تماماً)
    -- مدين = ذمم دائنة (المورد / accounts_payable)
    -- دائن = صندوق / بنك
    -- ===================================================================
        financial_transaction_id, line_number,
        account_id, account_type, currency_id,
        debit, credit, base_debit, base_credit,
        description, line_type, created_at
    ) VALUES (
        p_transaction_id, 1,
        v_ap_account_id, 'supplier', v_currency_id,
        v_amount, 0,
        v_amount * COALESCE(NULLIF(v_exchange_rate, 0), 1.0), 0,
        v_description, 'supplier_debit', NOW()
    );

        financial_transaction_id, line_number,
        account_id, account_type, currency_id,
        debit, credit, base_debit, base_credit,
        description, line_type, created_at
    ) VALUES (
        p_transaction_id, 2,
        v_cash_account_id, 'asset', v_currency_id,
        0, v_amount,
        0, v_amount * COALESCE(NULLIF(v_exchange_rate, 0), 1.0),
        v_description, 'cash_credit', NOW()
    );

    CALL sp_validate_journal_balance(p_transaction_id);

    UPDATE financial_transactions
       SET status       = 'posted',
           posted_by    = p_posted_by,
           posted_at    = NOW(),
           posted_ip    = v_posted_ip,
           updated_ip   = v_posted_ip
     WHERE id = p_transaction_id;

    -- معالجة توزيعات المدفوعات على فواتير المورد
    OPEN cur;
    cur_loop: LOOP
        FETCH cur INTO v_inv_id, v_alloc_amount;
        IF done = 1 THEN LEAVE cur_loop; END IF;
        IF v_inv_id IS NOT NULL AND v_alloc_amount > 0 THEN
            SELECT COALESCE(net_amount, total_amount - discount)
              INTO v_inv_net
              FROM invoices WHERE id = v_inv_id;

            IF v_inv_net IS NOT NULL THEN
                SELECT COALESCE(SUM(pa.allocated_amount), 0) INTO v_inv_paid
                  FROM payment_allocations pa
                  JOIN financial_transactions ft ON ft.id = pa.financial_transaction_id
                 WHERE pa.invoice_id = v_inv_id
                   AND ft.status = 'posted'
                   AND pa.financial_transaction_id <> p_transaction_id;

                SET v_alloc_rem = v_inv_net - v_inv_paid;
                IF v_alloc_amount > (v_alloc_rem + 0.01) THEN
                    SIGNAL SQLSTATE '45000'
                        SET MESSAGE_TEXT = 'تعذر إتمام العملية: توزيع مبلغ السند يتجاوز رصيد أحد الفواتير.';
                END IF;

                CALL sp_recalculate_invoice_payment(v_inv_id);
            END IF;
        END IF;
    END LOOP cur_loop;
    CLOSE cur;

    SET v_after_json = JSON_OBJECT(
        'id',                   CAST(p_transaction_id AS CHAR),
        'status',               'posted',
        'posted_by',            CAST(p_posted_by AS CHAR),
        'amount',               CAST(v_amount AS CHAR),
        'journal_lines_count',  CAST(2 AS CHAR)
    );

        user_id, action, table_name, record_id,
        old_values, new_values, ip_address, user_agent, created_at
    ) VALUES (
        COALESCE(p_posted_by, v_created_by, 0),
        'post', 'financial_transactions', p_transaction_id,
        CAST(v_before_json AS CHAR), CAST(v_after_json AS CHAR),
        v_posted_ip, v_posted_ua, NOW()
    );

    CALL sp_update_account_balances();

    COMMIT;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_post_receipt_voucher` (IN `p_transaction_id` INT, IN `p_posted_by` INT)  MODIFIES SQL DATA SQL SECURITY INVOKER COMMENT '[V2] ترحيل سند قبض — TX + EXIT HANDLER + رسائل عامة + تدقيق كامل' sp_post_rv_body:BEGIN
    DECLARE v_status          VARCHAR(20);
    DECLARE v_amount          DECIMAL(18,4);
    DECLARE v_currency_id     INT;
    DECLARE v_exchange_rate   DECIMAL(18,6);
    DECLARE v_party_account_id INT;
    DECLARE v_cash_bank_id    INT;
    DECLARE v_description     TEXT;
    DECLARE v_created_by      INT;
    DECLARE v_before_json     JSON;
    DECLARE v_after_json      JSON;
    DECLARE v_inv_id          INT;
    DECLARE v_alloc_amount    DECIMAL(18,4);
    DECLARE v_inv_net         DECIMAL(18,2);
    DECLARE v_inv_received    DECIMAL(18,2);
    DECLARE v_alloc_rem       DECIMAL(18,2);
    DECLARE v_posted_ip       VARCHAR(45) DEFAULT NULL;
    DECLARE v_posted_ua       TEXT        DEFAULT NULL;
    DECLARE v_ar_account_id   INT;
    DECLARE v_cash_account_id INT;
    DECLARE done INT DEFAULT 0;
    DECLARE cur CURSOR FOR
        SELECT invoice_id, allocated_amount
          FROM payment_allocations
         WHERE financial_transaction_id = p_transaction_id;
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        DECLARE v_ctx JSON;
        ROLLBACK;
        GET DIAGNOSTICS CONDITION 1
            @err_sqlstate = RETURNED_SQLSTATE,
            @err_msg      = MESSAGE_TEXT,
            @err_no       = MYSQL_ERRNO;
        SET v_ctx = JSON_OBJECT(
            'transaction_id', CAST(p_transaction_id AS CHAR),
            'posted_by',      CAST(p_posted_by AS CHAR),
            'mysql_errno',    CAST(@err_no AS CHAR),
            'sqlstate',       @err_sqlstate
        );
        CALL sp_log_error('sp_post_receipt_voucher', @err_msg, p_posted_by, v_ctx);
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'تعذر إتمام العملية. يرجى مراجعة البيانات والمحاولة مرة أخرى.';
    END;

    START TRANSACTION;

    -- (أ) التحقق من المدخلات
    IF p_transaction_id IS NULL OR p_transaction_id <= 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'تعذر إتمام العملية: معرف السند غير صالح.';
    END IF;

    -- (ب) جلب بيانات السند + التأكد من وجوده مع النوع الصحيح
    SELECT status, amount, currency_id, exchange_rate,
           party_account_id, cash_bank_account_id, description,
           COALESCE(created_by, 0)
      INTO v_status, v_amount, v_currency_id, v_exchange_rate,
           v_party_account_id, v_cash_bank_id, v_description, v_created_by
      FROM financial_transactions
     WHERE id = p_transaction_id AND transaction_type = 'receipt'
     LIMIT 1;

    IF v_status IS NULL THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'تعذر إتمام العملية: السند المطلوب غير متوفر.';
    END IF;

    IF v_status = 'posted' THEN
        LEAVE sp_post_rv_body;
    END IF;

    IF v_status <> 'draft' THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'تعذر إتمام العملية: حالة السند الحالية لا تسمح بالترحيل.';
    END IF;

    IF COALESCE(v_amount, 0) <= 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'تعذر إتمام العملية: مبلغ السند يجب أن يكون أكبر من صفر.';
    END IF;

    -- (ج) جلب معرفات الحسابات الافتراضية إذا لم يتم تمريرها
    SET v_ar_account_id = COALESCE(
        v_party_account_id,
        (SELECT id FROM unified_accounts WHERE account_type = 'accounts_receivable' LIMIT 1)
    );
    SET v_cash_account_id = COALESCE(
        v_cash_bank_id,
        (SELECT id FROM unified_accounts WHERE account_type IN ('box','bank') LIMIT 1)
    );

    IF v_ar_account_id IS NULL OR v_cash_account_id IS NULL THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'تعذر إتمام العملية: بعض الحسابات المحاسبية الأساسية غير مهيأة.';
    END IF;

    -- (د) جلب عنوان IP للمُرحّل (اختياري)
    IF p_posted_by IS NOT NULL THEN
        BEGIN
            DECLARE CONTINUE HANDLER FOR SQLEXCEPTION BEGIN END;
            SET v_posted_ip = (
                SELECT SUBSTRING_INDEX(
                    GROUP_CONCAT(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(new_values, '$.ip_address')), '')
                                 ORDER BY id DESC SEPARATOR '|'), '|', 1)
                  FROM audit_logs WHERE user_id = p_posted_by LIMIT 1
            );
        END;
    END IF;

    -- (هـ) لحظة ما قبل الترحيل
    SET v_before_json = JSON_OBJECT(
        'id',                   CAST(p_transaction_id AS CHAR),
        'status',               v_status,
        'amount',               CAST(v_amount AS CHAR),
        'currency_id',          CAST(v_currency_id AS CHAR),
        'party_account_id',     CAST(v_party_account_id AS CHAR),
        'cash_bank_account_id', CAST(v_cash_bank_id AS CHAR)
    );

    -- (و) إنشاء قيود اليومية (القبض: مدين = صندوق/بنك ، دائن = ذمم مدينة / العميل)
        financial_transaction_id, line_number,
        account_id, account_type, currency_id,
        debit, credit, base_debit, base_credit,
        description, line_type, created_at
    ) VALUES (
        p_transaction_id, 1,
        v_cash_account_id, 'asset', v_currency_id,
        v_amount, 0,
        v_amount * COALESCE(NULLIF(v_exchange_rate, 0), 1.0), 0,
        v_description, 'cash_debit', NOW()
    );

        financial_transaction_id, line_number,
        account_id, account_type, currency_id,
        debit, credit, base_debit, base_credit,
        description, line_type, created_at
    ) VALUES (
        p_transaction_id, 2,
        v_ar_account_id, 'customer', v_currency_id,
        0, v_amount,
        0, v_amount * COALESCE(NULLIF(v_exchange_rate, 0), 1.0),
        v_description, 'customer_credit', NOW()
    );

    -- (ز) التأكد من توازن قيود اليومية
    CALL sp_validate_journal_balance(p_transaction_id);

    -- (ح) تحديث حالة المعاملة إلى "مرحّل"
    UPDATE financial_transactions
       SET status       = 'posted',
           posted_by    = p_posted_by,
           posted_at    = NOW(),
           posted_ip    = v_posted_ip,
           updated_ip   = v_posted_ip
     WHERE id = p_transaction_id;

    -- (ط) معالجة توزيعات المبالغ على الفواتير + إعادة حساب المستحقات
    OPEN cur;
    cur_loop: LOOP
        FETCH cur INTO v_inv_id, v_alloc_amount;
        IF done = 1 THEN LEAVE cur_loop; END IF;
        IF v_inv_id IS NOT NULL AND v_alloc_amount > 0 THEN
            SELECT COALESCE(net_amount, total_amount - discount)
              INTO v_inv_net
              FROM invoices WHERE id = v_inv_id;

            IF v_inv_net IS NOT NULL THEN
                SELECT COALESCE(SUM(pa.allocated_amount), 0) INTO v_inv_received
                  FROM payment_allocations pa
                  JOIN financial_transactions ft ON ft.id = pa.financial_transaction_id
                 WHERE pa.invoice_id = v_inv_id
                   AND ft.status = 'posted'
                   AND pa.financial_transaction_id <> p_transaction_id;

                SET v_alloc_rem = v_inv_net - v_inv_received;
                IF v_alloc_amount > (v_alloc_rem + 0.01) THEN
                    SIGNAL SQLSTATE '45000'
                        SET MESSAGE_TEXT = 'تعذر إتمام العملية: توزيع مبلغ السند يتجاوز رصيد أحد الفواتير.';
                END IF;

                CALL sp_recalculate_invoice_payment(v_inv_id);
            END IF;
        END IF;
    END LOOP cur_loop;
    CLOSE cur;

    -- (ي) سجل المراجعة
    SET v_after_json = JSON_OBJECT(
        'id',                   CAST(p_transaction_id AS CHAR),
        'status',               'posted',
        'posted_by',            CAST(p_posted_by AS CHAR),
        'amount',               CAST(v_amount AS CHAR),
        'journal_lines_count',  CAST(2 AS CHAR)
    );

        user_id, action, table_name, record_id,
        old_values, new_values, ip_address, user_agent, created_at
    ) VALUES (
        COALESCE(p_posted_by, v_created_by, 0),
        'post', 'financial_transactions', p_transaction_id,
        CAST(v_before_json AS CHAR), CAST(v_after_json AS CHAR),
        v_posted_ip, v_posted_ua, NOW()
    );

    -- (ك) تحديث الأرصدة
    CALL sp_update_account_balances();

    COMMIT;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_process_expense_approval` (IN `p_voucher_id` INT, IN `p_approver_id` INT, IN `p_action` VARCHAR(20), IN `p_comment` TEXT)  MODIFIES SQL DATA SQL SECURITY INVOKER COMMENT '[الموافقات] موافقة/رفض مصروف — يعالج المستويات ويُحدث الحالة' sp_process_ea_body:BEGIN
    DECLARE v_curr_status       VARCHAR(50);
    DECLARE v_curr_approval     VARCHAR(50);
    DECLARE v_budget_id         INT;
    DECLARE v_exp_acc_id        INT;
    DECLARE v_amount            DECIMAL(18,4);
    DECLARE v_total_levels      INT;
    DECLARE v_approved_levels   INT;
    DECLARE v_action_ip         VARCHAR(45) DEFAULT NULL;
    DECLARE v_action_ua         TEXT        DEFAULT NULL;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        DECLARE v_ctx JSON;
        ROLLBACK;
        GET DIAGNOSTICS CONDITION 1
            @err_sqlstate = RETURNED_SQLSTATE,
            @err_msg      = MESSAGE_TEXT,
            @err_no       = MYSQL_ERRNO;
        SET v_ctx = JSON_OBJECT(
            'voucher_id',   CAST(p_voucher_id AS CHAR),
            'approver_id',  CAST(p_approver_id AS CHAR),
            'action',       p_action,
            'mysql_errno',  CAST(@err_no AS CHAR),
            'sqlstate',     @err_sqlstate
        );
        CALL sp_log_error('sp_process_expense_approval', @err_msg, p_approver_id, v_ctx);
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'تعذر إتمام العملية. يرجى مراجعة الصلاحيات والمحاولة مرة أخرى.';
    END;

    START TRANSACTION;

    IF p_voucher_id IS NULL THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'تعذر معالجة الموافقة: معرف المصروف غير صالح.';
        ROLLBACK;
    END IF;

    IF LOWER(p_action) NOT IN ('approve','reject') THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'تعذر معالجة الموافقة: نوع الإجراء غير صالح.';
        ROLLBACK;
    END IF;

    SELECT status, approval_status, budget_id, expense_account_id, total_amount
      INTO v_curr_status, v_curr_approval, v_budget_id, v_exp_acc_id, v_amount
      FROM expense_vouchers WHERE id = p_voucher_id LIMIT 1;

    IF v_curr_status IS NULL THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'تعذر معالجة الموافقة: سند المصروف غير موجود.';
        ROLLBACK;
    END IF;

    IF v_curr_status <> 'pending_approval' THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'تعذر معالجة الموافقة: المصروف ليس قيد الموافقة حالياً.';
        ROLLBACK;
    END IF;

    IF p_approver_id IS NOT NULL THEN
        BEGIN
            DECLARE CONTINUE HANDLER FOR SQLEXCEPTION BEGIN END;
            SET v_action_ip = (
                SELECT SUBSTRING_INDEX(
                    GROUP_CONCAT(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(new_values, '$.ip_address')), '')
                                 ORDER BY id DESC SEPARATOR '|'), '|', 1)
                  FROM audit_logs WHERE user_id = p_approver_id LIMIT 1
            );
        END;
    END IF;

    IF LOWER(p_action) = 'reject' THEN
        UPDATE expense_vouchers
           SET status          = 'rejected',
               approval_status = 'rejected'
         WHERE id = p_voucher_id;

        UPDATE expense_approvals
           SET action_taken = 'rejected',
               action_by    = p_approver_id,
               action_at    = NOW(),
               comment      = p_comment
         WHERE expense_voucher_id = p_voucher_id
           AND action_taken IS NULL
         ORDER BY approval_level ASC
         LIMIT 1;

        IF v_budget_id IS NOT NULL THEN
            CALL sp_consume_budget(v_budget_id, v_exp_acc_id, v_amount, 'uncommit');
        END IF;

                                old_values, new_values, ip_address, user_agent, created_at)
        VALUES (
            COALESCE(p_approver_id, 0),
            'reject', 'expense_vouchers', p_voucher_id,
            JSON_OBJECT('old_status', v_curr_status,
                        'old_approval', v_curr_approval),
            JSON_OBJECT('new_status','rejected','comment',LEFT(p_comment,500)),
            v_action_ip, v_action_ua, NOW()
        );

        COMMIT;
        LEAVE sp_process_ea_body;
    END IF;

    -- الموافقة: تحديث أول سجل موافقة معلق
    UPDATE expense_approvals
       SET action_taken = 'approved',
           action_by    = p_approver_id,
           action_at    = NOW(),
           comment      = p_comment
     WHERE expense_voucher_id = p_voucher_id
       AND action_taken IS NULL
     ORDER BY approval_level ASC
     LIMIT 1;

    SELECT COUNT(*), SUM(CASE WHEN action_taken = 'approved' THEN 1 ELSE 0 END)
      INTO v_total_levels, v_approved_levels
      FROM expense_approvals
     WHERE expense_voucher_id = p_voucher_id;

    IF v_total_levels = v_approved_levels THEN
        UPDATE expense_vouchers
           SET status          = 'approved',
               approval_status = 'fully_approved'
         WHERE id = p_voucher_id;
    ELSE
        UPDATE expense_vouchers
           SET approval_status = CONCAT('level_', v_approved_levels, '_approved')
         WHERE id = p_voucher_id;
    END IF;

                            old_values, new_values, ip_address, user_agent, created_at)
    VALUES (
        COALESCE(p_approver_id, 0),
        'approve', 'expense_vouchers', p_voucher_id,
        JSON_OBJECT('old_status', v_curr_status,
                    'approved_levels', CAST(v_approved_levels AS CHAR),
                    'total_levels', CAST(v_total_levels AS CHAR)),
        JSON_OBJECT('comment', LEFT(p_comment, 500)),
        v_action_ip, v_action_ua, NOW()
    );

    COMMIT;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_rebuild_balances` ()  MODIFIES SQL DATA SQL SECURITY INVOKER COMMENT '[PATCH:NO_TX] إعادة بناء الأرصدة — NO TX — UPDATE فقط، يحافظ على الافتتاحيات' BEGIN
    DROP TEMPORARY TABLE IF EXISTS tmp_rb_movements;
    CREATE TEMPORARY TABLE tmp_rb_movements (
        account_id     INT NOT NULL,
        currency_id    INT NOT NULL,
        movement       DECIMAL(18,2) NOT NULL DEFAULT 0,
        movement_base  DECIMAL(18,2) NOT NULL DEFAULT 0,
        PRIMARY KEY (account_id, currency_id)
    );
    SELECT
        jl.account_id,
        jl.currency_id,
        SUM(COALESCE(jl.debit, 0) - COALESCE(jl.credit, 0)) AS movement,
        SUM( (COALESCE(jl.debit, 0) - COALESCE(jl.credit, 0))
             * COALESCE(c.exchange_rate, 1.0) ) AS movement_base
      FROM journal_lines jl
      JOIN financial_transactions ft
        ON ft.id = jl.financial_transaction_id
       AND ft.status = 'posted'
      LEFT JOIN currencies c
        ON c.id = jl.currency_id
     GROUP BY jl.account_id, jl.currency_id;
    UPDATE account_balances_unified abu
      LEFT JOIN tmp_rb_movements m
             ON m.account_id  = abu.account_id
            AND m.currency_id = abu.currency_id
      LEFT JOIN currencies curr
             ON curr.id = abu.currency_id
       SET abu.current_balance      = COALESCE(abu.opening_balance, 0)      + COALESCE(m.movement, 0),
           abu.current_balance_base = COALESCE(abu.opening_balance_base, 0) + COALESCE(m.movement_base, 0),
           abu.currency_code        = COALESCE(curr.currency_code, abu.currency_code),
           abu.last_updated         = NOW()
     WHERE abu.id IS NOT NULL;
    DROP TEMPORARY TABLE IF EXISTS tmp_rb_movements;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_recalculate_invoice_payment` (IN `p_invoice_id` INT)  MODIFIES SQL DATA SQL SECURITY INVOKER COMMENT '[فقرة-2/6] تحديث تلقائي لـ amount_received و payment_status للفاتورة' BEGIN
    DECLARE v_net      DECIMAL(18,2);
    DECLARE v_received DECIMAL(18,2);
    IF p_invoice_id IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'sp_recalculate_invoice_payment: معرف الفاتورة فارغ';
    END IF;
    SELECT COALESCE(net_amount, total_amount - discount)
      INTO v_net
      FROM invoices WHERE id = p_invoice_id;
    IF v_net IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'sp_recalculate_invoice_payment: الفاتورة غير موجودة';
    END IF;
    SELECT COALESCE(SUM(pa.allocated_amount), 0) INTO v_received
      FROM payment_allocations pa
      JOIN financial_transactions ft ON ft.id = pa.financial_transaction_id
     WHERE pa.invoice_id = p_invoice_id
       AND ft.status = 'posted';
    UPDATE invoices
       SET amount_received = v_received,
           payment_status  = CASE
               WHEN v_received >= (v_net - 0.01) THEN 'fully_paid'
               WHEN v_received > 0.01              THEN 'partial'
               ELSE 'unpaid'
           END
     WHERE id = p_invoice_id;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_unpost_invoice` (IN `p_invoice_id` INT, IN `p_posted_by` INT)  MODIFIES SQL DATA SQL SECURITY INVOKER COMMENT '[V2] إلغاء ترحيل فاتورة — TX + EXIT HANDLER + تدقيق + تحديث أرصدة + توزيعات' sp_unpost_invoice_body:BEGIN
    DECLARE v_status        VARCHAR(20);
    DECLARE v_before_json   JSON;
    DECLARE v_after_json    JSON;
    DECLARE v_cancelled_ip  VARCHAR(45) DEFAULT NULL;
    DECLARE v_cancelled_ua  TEXT        DEFAULT NULL;
    DECLARE v_created_by    INT;
    DECLARE v_inv_id        INT;
    DECLARE v_category      VARCHAR(20);
    DECLARE v_tx_id         INT;
    DECLARE done INT DEFAULT 0;

    -- المؤشر 1: فواتير متأثرة بتوزيعات الدفع
    DECLARE cur_invoices CURSOR FOR
        SELECT DISTINCT pa.invoice_id
          FROM payment_allocations pa
          JOIN financial_transactions ft ON ft.id = pa.financial_transaction_id
         WHERE ft.reference_id   = p_invoice_id
           AND ft.reference_type = 'invoice'
           AND ft.transaction_type IN ('invoice','purchase');

    -- المؤشر 2: جميع فواتير العميل/المورد لإعادة حساب التوزيعات بعد الحذف
    DECLARE cur_party CURSOR FOR
        SELECT DISTINCT i.id
          FROM invoices i
         WHERE i.id IN (
             SELECT DISTINCT invoice_id FROM payment_allocations pa
              WHERE EXISTS (
                  SELECT 1 FROM financial_transactions ft
                   WHERE ft.id = pa.financial_transaction_id
                     AND ((ft.reference_id = p_invoice_id AND ft.reference_type = 'invoice') OR
                          (pa.invoice_id = p_invoice_id))
              )
         );
    DECLARE CONTINUE HANDLER FOR NOT FOUND SET done = 1;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        DECLARE v_ctx JSON;
        ROLLBACK;
        GET DIAGNOSTICS CONDITION 1
            @err_sqlstate = RETURNED_SQLSTATE,
            @err_msg      = MESSAGE_TEXT,
            @err_no       = MYSQL_ERRNO;
        SET v_ctx = JSON_OBJECT(
            'invoice_id', CAST(p_invoice_id AS CHAR),
            'posted_by',  CAST(p_posted_by AS CHAR),
            'mysql_errno',CAST(@err_no AS CHAR),
            'sqlstate',   @err_sqlstate
        );
        CALL sp_log_error('sp_unpost_invoice', @err_msg, p_posted_by, v_ctx);
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'تعذر إتمام العملية. يرجى مراجعة البيانات والمحاولة مرة أخرى.';
    END;

    START TRANSACTION;

    IF p_invoice_id IS NULL OR p_invoice_id <= 0 THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'تعذر إتمام العملية: معرف الفاتورة غير صالح.';
    END IF;

    SELECT invoice_status, COALESCE(created_by, 0), invoice_category
      INTO v_status, v_created_by, v_category
      FROM invoices
     WHERE id = p_invoice_id
     LIMIT 1;

    IF v_status IS NULL THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'تعذر إتمام العملية: الفاتورة المطلوبة غير متوفرة.';
    END IF;

    IF v_status = 'draft' THEN
        LEAVE sp_unpost_invoice_body;
    END IF;

    IF v_status NOT IN ('posted','partial') THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'تعذر إتمام العملية: حالة الفاتورة الحالية لا تسمح بالإلغاء.';
    END IF;

    -- تأمين: وجود سندات قبض/صرف مرتبطة ومُرحّلة تمنع الإلغاء
    IF EXISTS (
        SELECT 1 FROM payment_allocations pa
          JOIN financial_transactions ft ON ft.id = pa.financial_transaction_id
         WHERE pa.invoice_id = p_invoice_id AND ft.status = 'posted'
    ) THEN
        SIGNAL SQLSTATE '45000'
            SET MESSAGE_TEXT = 'تعذر إتمام العملية: توجد سندات قبض أو صرف مرتبطة بالفاتورة وقائمة.';
    END IF;

    IF p_posted_by IS NOT NULL THEN
        BEGIN
            DECLARE CONTINUE HANDLER FOR SQLEXCEPTION BEGIN END;
            SET v_cancelled_ip = (
                SELECT SUBSTRING_INDEX(
                    GROUP_CONCAT(COALESCE(JSON_UNQUOTE(JSON_EXTRACT(new_values, '$.ip_address')), '')
                                 ORDER BY id DESC SEPARATOR '|'), '|', 1)
                  FROM audit_logs WHERE user_id = p_posted_by LIMIT 1
            );
        END;
    END IF;

    SET v_before_json = JSON_OBJECT(
        'id',               CAST(p_invoice_id AS CHAR),
        'invoice_category', v_category,
        'invoice_status',   v_status
    );

    -- (1) حذف قيود اليومية المرتبطة بترحيل الفاتورة
    DELETE jl
      FROM journal_lines jl
      JOIN financial_transactions ft
        ON ft.id = jl.financial_transaction_id
     WHERE ft.reference_id   = p_invoice_id
       AND ft.reference_type = 'invoice'
       AND ft.transaction_type IN ('invoice','purchase');

    -- (2) تحديث حالة معاملات الفاتورة المالية إلى ملغى
    UPDATE financial_transactions
       SET status       = 'cancelled',
           cancelled_by = p_posted_by,
           cancelled_at = NOW(),
           cancelled_ip = v_cancelled_ip,
           updated_ip   = v_cancelled_ip
     WHERE reference_id   = p_invoice_id
       AND reference_type = 'invoice'
       AND transaction_type IN ('invoice','purchase');

    -- (3) عكس حالة الفاتورة إلى مسودة
    UPDATE invoices
       SET invoice_status = 'draft',
           posted_by   = NULL,
           posted_at   = NULL
     WHERE id = p_invoice_id;

    -- (4) إعادة حساب توزيعات الفواتير المتأثرة
    SET done = 0;
    OPEN cur_invoices;
    cur1_loop: LOOP
        FETCH cur_invoices INTO v_inv_id;
        IF done = 1 THEN LEAVE cur1_loop; END IF;
        IF v_inv_id IS NOT NULL THEN
            CALL sp_recalculate_invoice_payment(v_inv_id);
        END IF;
    END LOOP cur1_loop;
    CLOSE cur_invoices;

    -- إعادة حساب فاتورة نفسها
    CALL sp_recalculate_invoice_payment(p_invoice_id);

    SET v_after_json = JSON_OBJECT(
        'id',               CAST(p_invoice_id AS CHAR),
        'invoice_status',   'draft',
        'cancelled_by',     CAST(p_posted_by AS CHAR),
        'cancelled_at',     DATE_FORMAT(NOW(), '%Y-%m-%d %H:%i:%s')
    );

        user_id, action, table_name, record_id,
        old_values, new_values, ip_address, user_agent, created_at
    ) VALUES (
        COALESCE(p_posted_by, v_created_by, 0),
        'unpost', 'invoices', p_invoice_id,
        CAST(v_before_json AS CHAR), CAST(v_after_json AS CHAR),
        v_cancelled_ip, v_cancelled_ua, NOW()
    );

    -- (5) تحديث أرصدة الحسابات
    CALL sp_update_account_balances();

    COMMIT;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_update_account_balances` (IN `p_transaction_id` INT)  MODIFIES SQL DATA SQL SECURITY INVOKER COMMENT '[فقرة-2] واجهة تحديث أرصدة الحسابات — يحافظ على الافتتاحيات' BEGIN
    CALL sp_rebuild_balances();
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_validate_journal_balance` (IN `p_transaction_id` INT)  READS SQL DATA SQL SECURITY INVOKER COMMENT '[محاسبي] تحقق توازن مدين=دائن — يلقي SIGNAL عند عدم التوازن' BEGIN
    DECLARE v_debit  DECIMAL(18,2);
    DECLARE v_credit DECIMAL(18,2);
    DECLARE v_diff   DECIMAL(18,2);
    IF p_transaction_id IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'sp_validate_journal_balance: معرف المعاملة فارغ';
    END IF;
    SELECT
        COALESCE(SUM(debit),  0),
        COALESCE(SUM(credit), 0),
        ABS(COALESCE(SUM(debit), 0) - COALESCE(SUM(credit), 0))
      INTO v_debit, v_credit, v_diff
      FROM journal_lines
     WHERE financial_transaction_id = p_transaction_id;
    IF v_diff > 0.01 THEN
        SET @err_msg = CONCAT(
            'sp_validate_journal_balance: المعاملة #',
            CAST(p_transaction_id AS CHAR),
            ' غير متوازنة — مدين=', CAST(v_debit AS CHAR),
            ' ، دائن=', CAST(v_credit AS CHAR),
            ' ، الفرق=', CAST(v_diff AS CHAR)
        );
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = @err_msg;
    END IF;
END$$

CREATE DEFINER=`root`@`localhost` PROCEDURE `_patch_financial_delete_permissions` ()  MODIFIES SQL DATA BEGIN
    DECLARE v_admin_role_id INT DEFAULT NULL;
    DECLARE v_developer_role_id INT DEFAULT NULL;

    
    
    DROP TEMPORARY TABLE IF EXISTS _new_perms;
    CREATE TEMPORARY TABLE _new_perms (
        permission_code VARCHAR(100) NOT NULL PRIMARY KEY,
        display_name VARCHAR(200) NOT NULL,
        category VARCHAR(50) NOT NULL DEFAULT 'finance',
        description VARCHAR(500) NULL
    ) ENGINE=MEMORY;


    
    SELECT p.permission_code, p.display_name, p.category, p.description, 1, NOW(), NOW()
      FROM _new_perms p
     WHERE NOT EXISTS (
        SELECT 1 FROM unified_permissions up
         WHERE up.permission_code = p.permission_code
     );

    
    SELECT id INTO v_developer_role_id FROM roles WHERE LOWER(name) = 'developer' OR id = 2 LIMIT 1;
    SELECT id INTO v_admin_role_id     FROM roles WHERE LOWER(name) IN ('admin','????????_????????????','???????? ????????????') OR display_name LIKE '%???????? ????????????%' LIMIT 1;

    
    IF v_developer_role_id IS NOT NULL THEN
        SELECT v_developer_role_id, up.id, 1, NOW()
          FROM unified_permissions up
         WHERE up.permission_code IN (SELECT permission_code FROM _new_perms);
    END IF;

    
    IF v_admin_role_id IS NOT NULL AND (v_developer_role_id IS NULL OR v_admin_role_id <> v_developer_role_id) THEN
        SELECT v_admin_role_id, up.id, 1, NOW()
          FROM unified_permissions up
         WHERE up.permission_code IN (SELECT permission_code FROM _new_perms);
    END IF;

    DROP TEMPORARY TABLE IF EXISTS _new_perms;
END$$

