CREATE DEFINER=`root`@`localhost` FUNCTION `fn_check_budget_availability` (`p_budget_id` INT, `p_expense_account_id` INT, `p_requested_amount` DECIMAL(18,4)) RETURNS TINYINT(1) READS SQL DATA SQL SECURITY INVOKER COMMENT '[الميزانيات] هل يوجد رصيد كافٍ في الميزانية لهذا البند؟ (1=نعم 0=لا)' BEGIN
    DECLARE v_alloc   DECIMAL(18,4) DEFAULT 0;
    DECLARE v_used    DECIMAL(18,4) DEFAULT 0;
    DECLARE v_remain  DECIMAL(18,4) DEFAULT 0;

    IF p_budget_id IS NULL OR p_expense_account_id IS NULL THEN
        RETURN 1;
    END IF;

    SELECT allocated_amount, (consumed_amount + committed_amount)
      INTO v_alloc, v_used
      FROM budget_allocations
     WHERE budget_id          = p_budget_id
       AND expense_account_id = p_expense_account_id
     LIMIT 1;

    IF v_alloc IS NULL THEN
        RETURN 0;
    END IF;

    SET v_remain = v_alloc - v_used;
    RETURN (v_remain + 0.01) >= COALESCE(p_requested_amount, 0);
END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_convert_currency` (`p_amount` DECIMAL(18,4), `p_from_curr_id` INT, `p_to_curr_id` INT) RETURNS DECIMAL(18,4) DETERMINISTIC SQL SECURITY INVOKER COMMENT '[فقرة-7] تحويل عملات — التحقق من وجود العملة + منع القسمة على صفر' BEGIN
    DECLARE v_rate_from    DECIMAL(18,6);
    DECLARE v_rate_to      DECIMAL(18,6);
    DECLARE v_from_exists  INT DEFAULT 0;
    DECLARE v_to_exists    INT DEFAULT 0;
    IF p_amount IS NULL THEN
        RETURN NULL;
    END IF;
    IF p_amount = 0 THEN
        RETURN 0.0000;
    END IF;
    IF p_from_curr_id IS NULL OR p_to_curr_id IS NULL THEN
        RETURN p_amount;
    END IF;
    IF p_from_curr_id = p_to_curr_id THEN
        RETURN p_amount;
    END IF;
    SELECT COUNT(*) INTO v_from_exists FROM currencies WHERE id = p_from_curr_id;
    SELECT COUNT(*) INTO v_to_exists   FROM currencies WHERE id = p_to_curr_id;
    IF v_from_exists = 0 OR v_to_exists = 0 THEN
        RETURN p_amount;
    END IF;
    SELECT COALESCE(exchange_rate, 1.0) INTO v_rate_from
      FROM currencies WHERE id = p_from_curr_id LIMIT 1;
    SELECT COALESCE(exchange_rate, 1.0) INTO v_rate_to
      FROM currencies WHERE id = p_to_curr_id LIMIT 1;
    IF v_rate_from IS NULL OR v_rate_from <= 0 THEN SET v_rate_from = 1.0; END IF;
    IF v_rate_to   IS NULL OR v_rate_to   <= 0 THEN SET v_rate_to   = 1.0; END IF;
    RETURN ROUND( (p_amount * v_rate_from) / v_rate_to, 4 );
END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_convert_to_base_currency` (`p_amount` DECIMAL(18,4), `p_curr_id` INT) RETURNS DECIMAL(18,4) DETERMINISTIC SQL SECURITY INVOKER COMMENT '[فقرة-7] تحويل للعملة الأساسية — اختيار ديناميكي + تعامل مع NULL' BEGIN
    DECLARE v_rate        DECIMAL(18,6);
    DECLARE v_base_curr   INT;
    DECLARE v_curr_exists INT DEFAULT 0;
    IF p_amount IS NULL THEN
        RETURN NULL;
    END IF;
    IF p_amount = 0 THEN
        RETURN 0.0000;
    END IF;
    IF p_curr_id IS NULL THEN
        RETURN p_amount;
    END IF;
    SELECT COUNT(*) INTO v_curr_exists FROM currencies WHERE id = p_curr_id;
    IF v_curr_exists = 0 THEN
        RETURN p_amount;
    END IF;
    SELECT id INTO v_base_curr
      FROM currencies
     WHERE exchange_rate = 1.0 AND is_active = 1
     ORDER BY is_default DESC, id ASC
     LIMIT 1;
    IF v_base_curr IS NULL THEN
        SELECT id INTO v_base_curr
          FROM currencies
         WHERE is_default = 1
         ORDER BY id ASC LIMIT 1;
    END IF;
    IF v_base_curr IS NULL THEN
        SELECT MIN(id) INTO v_base_curr FROM currencies;
    END IF;
    IF v_base_curr IS NOT NULL AND p_curr_id = v_base_curr THEN
        RETURN p_amount;
    END IF;
    SELECT COALESCE(exchange_rate, 1.0) INTO v_rate
      FROM currencies WHERE id = p_curr_id LIMIT 1;
    IF v_rate IS NULL OR v_rate <= 0 THEN
        SET v_rate = 1.0;
    END IF;
    RETURN ROUND( p_amount * v_rate, 4 );
END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_get_default_leaf_account` (`p_parent_account_code` VARCHAR(50)) RETURNS INT(11) DETERMINISTIC SQL SECURITY INVOKER COMMENT '[محاسبي] إرجاع أول حساب ورقة تحت أصل معين حسب الكود' BEGIN
    DECLARE v_parent_id   INT;
    DECLARE v_leaf_id     INT;
    DECLARE v_has_children INT;
    IF p_parent_account_code IS NULL OR LENGTH(TRIM(p_parent_account_code)) = 0 THEN
        RETURN NULL;
    END IF;
    SELECT id INTO v_parent_id
      FROM unified_accounts
     WHERE account_code = TRIM(p_parent_account_code)
     LIMIT 1;
    IF v_parent_id IS NULL THEN
        CASE TRIM(p_parent_account_code)
            WHEN '11101' THEN
                SELECT id INTO v_parent_id FROM unified_accounts WHERE account_code = '11101001' LIMIT 1;
            WHEN '11102' THEN
                SELECT id INTO v_parent_id FROM unified_accounts WHERE account_code = '11102001' LIMIT 1;
            ELSE
                SELECT id INTO v_parent_id
                  FROM unified_accounts
                 WHERE account_code LIKE CONCAT(TRIM(p_parent_account_code), '%')
                 ORDER BY LENGTH(account_code) ASC, account_code ASC
                 LIMIT 1;
        END CASE;
    END IF;
    IF v_parent_id IS NULL THEN
        RETURN NULL;
    END IF;
    SELECT COUNT(*) INTO v_has_children
      FROM unified_accounts
     WHERE parent_id = v_parent_id;
    IF v_has_children = 0 THEN
        RETURN v_parent_id;
    END IF;
    SELECT id INTO v_leaf_id
      FROM unified_accounts
     WHERE parent_id = v_parent_id
       AND id NOT IN (SELECT COALESCE(parent_id, 0) FROM unified_accounts WHERE parent_id IS NOT NULL)
     ORDER BY account_code ASC
     LIMIT 1;
    IF v_leaf_id IS NULL THEN
        SELECT id INTO v_leaf_id
          FROM unified_accounts
         WHERE parent_id = v_parent_id
         ORDER BY account_code ASC
         LIMIT 1;
    END IF;
    RETURN v_leaf_id;
END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_get_next_sequence` (`p_sequence_name` VARCHAR(50)) RETURNS VARCHAR(50) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci MODIFIES SQL DATA SQL SECURITY INVOKER COMMENT '[محاسبي] توليد تسلسل فريد عبر جدول sequence_numbers — لا يكرر عند الحذف' BEGIN
    DECLARE v_prefix     VARCHAR(10);
    DECLARE v_year       VARCHAR(4);
    DECLARE v_next_num   INT;
    DECLARE v_seq_sname  VARCHAR(50);
    IF p_sequence_name IS NULL OR LENGTH(TRIM(p_sequence_name)) = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fn_get_next_sequence: اسم التسلسل فارغ';
    END IF;
    SET v_seq_sname = LOWER(TRIM(p_sequence_name));
    SET v_year      = YEAR(CURDATE());
    CASE v_seq_sname
        WHEN 'receipt'            THEN SET v_prefix = 'RCT';
        WHEN 'payment'            THEN SET v_prefix = 'PMT';
        WHEN 'invoice'            THEN SET v_prefix = 'INV';
        WHEN 'purchase'           THEN SET v_prefix = 'PUR';
        WHEN 'journal'            THEN SET v_prefix = 'JRN';
        WHEN 'exch'               THEN SET v_prefix = 'EXH';
        WHEN 'busflight_invoice'  THEN SET v_prefix = 'BFI';
        WHEN 'umrah_invoice'      THEN SET v_prefix = 'UMR';
        WHEN 'work_visa_invoice'  THEN SET v_prefix = 'WVI';
        WHEN 'family_visit_invoice' THEN SET v_prefix = 'FVI';
        WHEN 'passport_invoice'   THEN SET v_prefix = 'PSI';
        WHEN 'purchase_invoice'   THEN SET v_prefix = 'PUI';
        ELSE SET v_prefix = UPPER(LEFT(v_seq_sname, 3));
    END CASE;
    VALUES (v_seq_sname, 1, v_year)
    ON DUPLICATE KEY UPDATE
        last_number = IF(year = VALUES(year), last_number + 1, 1),
        year        = VALUES(year);
    SELECT last_number INTO v_next_num
      FROM sequence_numbers
     WHERE sequence_name = v_seq_sname
     LIMIT 1;
    IF v_next_num IS NULL THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'fn_get_next_sequence: فشل قراءة التسلسل';
    END IF;
    RETURN CONCAT(v_prefix, '-', RIGHT(v_year, 2), '-', LPAD(v_next_num, 5, '0'));
END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_sanitize_input` (`p_input` VARCHAR(1000)) RETURNS VARCHAR(1000) CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci DETERMINISTIC SQL SECURITY INVOKER COMMENT '[SQLi] توافق قديم — تنقية صارمة للمعرفات والأسماء' BEGIN
    RETURN CAST(fn_sanitize_safe(p_input, 1) AS CHAR);
END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_sanitize_safe` (`p_input` TEXT, `p_strict` TINYINT) RETURNS TEXT CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci DETERMINISTIC SQL SECURITY INVOKER COMMENT '[SQLi] تنقية شاملة — strict=1 للأسماء / 0 للوصفات' BEGIN
    IF p_input IS NULL THEN
        RETURN NULL;
    END IF;
    SET p_input = REPLACE(p_input, "'", "''");
    SET p_input = REPLACE(p_input, "\\", "\\\\");
    SET p_input = REPLACE(p_input, CHAR(34), CONCAT(CHAR(92), CHAR(34)));
    SET p_input = REPLACE(p_input, ";", "");
    SET p_input = REPLACE(p_input, "--", "");
    SET p_input = REPLACE(p_input, "/*", "");
    SET p_input = REPLACE(p_input, "*/", "");
    SET p_input = REPLACE(p_input, "xp_", "");
    IF COALESCE(p_strict, 1) = 1 THEN
        IF LOWER(p_input) LIKE '%exec%'     OR LOWER(p_input) LIKE '%union%'  OR
           LOWER(p_input) LIKE '%select%'   OR LOWER(p_input) LIKE '%drop%'   OR
           LOWER(p_input) LIKE '%delete%'   OR LOWER(p_input) LIKE '%insert%' OR
           LOWER(p_input) LIKE '%update%'   OR LOWER(p_input) LIKE '%alter%'  OR
           LOWER(p_input) LIKE '%create%'   OR LOWER(p_input) LIKE '%truncate%' THEN
            SET p_input = REPLACE(REPLACE(LOWER(p_input), 'exec', ''), 'xp_', '');
            SET p_input = REPLACE(p_input, 'union',    '');
            SET p_input = REPLACE(p_input, 'select',   '');
            SET p_input = REPLACE(p_input, 'drop',     '');
            SET p_input = REPLACE(p_input, 'delete',   '');
            SET p_input = REPLACE(p_input, 'insert',   '');
            SET p_input = REPLACE(p_input, 'update',   '');
            SET p_input = REPLACE(p_input, 'alter',    '');
            SET p_input = REPLACE(p_input, 'create',   '');
            SET p_input = REPLACE(p_input, 'truncate', '');
        END IF;
    END IF;
    RETURN TRIM(p_input);
END$$

CREATE DEFINER=`root`@`localhost` FUNCTION `fn_sanitize_text` (`p_input` TEXT) RETURNS TEXT CHARSET utf8mb4 COLLATE utf8mb4_unicode_ci DETERMINISTIC SQL SECURITY INVOKER COMMENT '[SQLi] توافق قديم — تنقية لينة للوصفات والنصوص' BEGIN
    RETURN fn_sanitize_safe(p_input, 0);
END$$

