--
-- القوادح `financial_transactions`
--
DELIMITER $$
CREATE TRIGGER `trg_financial_transactions_check_bi` BEFORE INSERT ON `financial_transactions` FOR EACH ROW BEGIN
    SET NEW.amount        = GREATEST(COALESCE(NEW.amount,        0), 0);
    SET NEW.exchange_rate = GREATEST(COALESCE(NEW.exchange_rate, 1), 0.0001);
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_financial_transactions_check_bu` BEFORE UPDATE ON `financial_transactions` FOR EACH ROW BEGIN
    SET NEW.amount        = GREATEST(COALESCE(NEW.amount,        0), 0);
    SET NEW.exchange_rate = GREATEST(COALESCE(NEW.exchange_rate, 1), 0.0001);
END
$$
DELIMITER ;

