  `payment_type` varchar(50) DEFAULT NULL COMMENT 'نوع الدفع: cash | credit | bank_transfer | etc.',
  `delivery_type` varchar(50) DEFAULT NULL COMMENT 'نوع التسليم: cash | credit',
  `account_id` int(11) DEFAULT NULL,
  `customer_account_id` int(11) DEFAULT NULL,
