) ;

--
-- إرجاع أو استيراد بيانات الجدول `invoices`
--


--
-- القوادح `invoices`
--
DELIMITER $$
CREATE TRIGGER `trg_invoices_check_bi` BEFORE INSERT ON `invoices` FOR EACH ROW BEGIN
    SET NEW.total_amount    = GREATEST(COALESCE(NEW.total_amount,    0), 0);
    SET NEW.discount        = GREATEST(COALESCE(NEW.discount,        0), 0);
    SET NEW.tax_amount      = GREATEST(COALESCE(NEW.tax_amount,      0), 0);
    SET NEW.tax_rate        = GREATEST(COALESCE(NEW.tax_rate,        0), 0);
    SET NEW.cost_amount     = GREATEST(COALESCE(NEW.cost_amount,     0), 0);
    SET NEW.amount_received = GREATEST(COALESCE(NEW.amount_received, 0), 0);
    IF NEW.net_amount IS NULL OR NEW.net_amount = 0 THEN
        SET NEW.net_amount = GREATEST(NEW.total_amount - NEW.discount + NEW.tax_amount, 0);
    END IF;
    SET NEW.net_amount = GREATEST(NEW.net_amount, 0);
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_invoices_check_bu` BEFORE UPDATE ON `invoices` FOR EACH ROW BEGIN
    SET NEW.total_amount    = GREATEST(COALESCE(NEW.total_amount,    0), 0);
    SET NEW.discount        = GREATEST(COALESCE(NEW.discount,        0), 0);
    SET NEW.tax_amount      = GREATEST(COALESCE(NEW.tax_amount,      0), 0);
    SET NEW.tax_rate        = GREATEST(COALESCE(NEW.tax_rate,        0), 0);
    SET NEW.cost_amount     = GREATEST(COALESCE(NEW.cost_amount,     0), 0);
    SET NEW.amount_received = GREATEST(COALESCE(NEW.amount_received, 0), 0);
    IF NEW.net_amount IS NULL OR NEW.net_amount = 0 THEN
        SET NEW.net_amount = GREATEST(NEW.total_amount - NEW.discount + NEW.tax_amount, 0);
    END IF;
    SET NEW.net_amount = GREATEST(NEW.net_amount, 0);
END
$$
DELIMITER ;

