  `debit` decimal(15,2) DEFAULT 0.00,
  `credit` decimal(15,2) DEFAULT 0.00,
  `currency_id` int(11) NOT NULL,
  `description` text DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

--
-- إرجاع أو استيراد بيانات الجدول `journal_lines`
--


--
-- القوادح `journal_lines`
--
DELIMITER $$
CREATE TRIGGER `trg_journal_lines_check_bi` BEFORE INSERT ON `journal_lines` FOR EACH ROW BEGIN
    IF NEW.debit IS NULL THEN
        SET NEW.debit = 0;
    END IF;
    IF NEW.credit IS NULL THEN
        SET NEW.credit = 0;
    END IF;
    IF NEW.debit < 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'journal_lines: القيمة المدينة لا يمكن أن تكون سالبة';
    END IF;
    IF NEW.credit < 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'journal_lines: القيمة الدائنة لا يمكن أن تكون سالبة';
    END IF;
END
$$
DELIMITER ;
DELIMITER $$
CREATE TRIGGER `trg_journal_lines_check_bu` BEFORE UPDATE ON `journal_lines` FOR EACH ROW BEGIN
    IF NEW.debit IS NULL THEN
        SET NEW.debit = 0;
