--
-- Structure for view `documents`
--
DROP TABLE IF EXISTS `documents`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY INVOKER VIEW `documents`  AS SELECT `financial_transactions`.`id` AS `id`, `financial_transactions`.`transaction_number` AS `document_number`, `financial_transactions`.`transaction_date` AS `document_date`, `financial_transactions`.`transaction_type` AS `document_type`, `financial_transactions`.`amount` AS `amount`, `financial_transactions`.`currency_id` AS `currency_id`, `financial_transactions`.`status` AS `status`, `financial_transactions`.`reference_type` AS `reference_type`, `financial_transactions`.`reference_id` AS `reference_id` FROM `financial_transactions` ;

-- --------------------------------------------------------

--
-- Structure for view `v_budget_vs_actual`
--
DROP TABLE IF EXISTS `v_budget_vs_actual`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_budget_vs_actual`  AS SELECT `b`.`fiscal_year` AS `fiscal_year`, `b`.`budget_name` AS `budget_name`, `b`.`budget_period` AS `budget_period`, `b`.`period_number` AS `period_number`, `b`.`status` AS `budget_status`, coalesce(`cc`.`center_name_ar`,concat('مركز ',`cc`.`center_code`)) AS `cost_center_name`, coalesce(`ua`.`account_name_ar`,concat('حساب ',`ua`.`account_code`)) AS `expense_account`, `ba`.`allocated_amount` AS `allocated_amount`, `ba`.`consumed_amount` AS `consumed_amount`, `ba`.`committed_amount` AS `committed_amount`, `ba`.`allocated_amount`- `ba`.`consumed_amount` - `ba`.`committed_amount` AS `remaining_amount`, CASE WHEN `ba`.`allocated_amount` > 0 THEN round((`ba`.`consumed_amount` + `ba`.`committed_amount`) / `ba`.`allocated_amount` * 100,2) ELSE 0 END AS `consumption_percent`, CASE WHEN `ba`.`allocated_amount` > 0 AND `ba`.`consumed_amount` + `ba`.`committed_amount` > `ba`.`allocated_amount` THEN 'overrun' WHEN `ba`.`allocated_amount` > 0 AND (`ba`.`consumed_amount` + `ba`.`committed_amount`) / `ba`.`allocated_amount` >= 0.80 THEN 'warning' ELSE 'on_track' END AS `budget_status_flag` FROM (((`budget_allocations` `ba` join `budgets` `b` on(`b`.`id` = `ba`.`budget_id`)) join `unified_accounts` `ua` on(`ua`.`id` = `ba`.`expense_account_id`)) left join `cost_centers` `cc` on(`cc`.`id` = `b`.`cost_center_id`)) ;

-- --------------------------------------------------------

--
-- Structure for view `v_expense_summary_by_category`
--
DROP TABLE IF EXISTS `v_expense_summary_by_category`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_expense_summary_by_category`  AS SELECT extract(year_month from `ev`.`voucher_date`) AS `period_ym`, date_format(`ev`.`voucher_date`,'%Y-%m') AS `period_label`, coalesce(`ua`.`account_name_ar`,concat('حساب ',`ua`.`account_code`)) AS `expense_account_name`, `ua`.`account_code` AS `expense_account_code`, coalesce(`cc`.`center_name_ar`,concat('مركز ',`cc`.`center_code`)) AS `cost_center_name`, `ev`.`status` AS `voucher_status`, count(0) AS `voucher_count`, sum(`ev`.`total_amount`) AS `total_amount`, sum(`ev`.`tax_amount`) AS `total_tax`, sum(`ev`.`equivalent_amount`) AS `total_equivalent`, sum(case when `ev`.`budget_id` is null then `ev`.`total_amount` else 0 end) AS `amount_without_budget` FROM ((`expense_vouchers` `ev` join `unified_accounts` `ua` on(`ua`.`id` = `ev`.`expense_account_id`)) left join `cost_centers` `cc` on(`cc`.`id` = `ev`.`cost_center_id`)) WHERE `ev`.`status` <> 'cancelled' GROUP BY extract(year_month from `ev`.`voucher_date`), date_format(`ev`.`voucher_date`,'%Y-%m'), coalesce(`ua`.`account_name_ar`,concat('حساب ',`ua`.`account_code`)), `ua`.`account_code`, coalesce(`cc`.`center_name_ar`,concat('مركز ',`cc`.`center_code`)), `ev`.`status` ORDER BY extract(year_month from `ev`.`voucher_date`) DESC, sum(`ev`.`total_amount`) DESC ;

